{"topic_language":"...","topic_kind":"entity|question|concept|event|other","candidates":[{"candidate_id":"C1","canonical_name":"...","subject_type":"...","context":"...","interpretation":"...","discovery_query":"..."}]}

Rules:
- Produce 2-5 genuinely distinct plausible meanings when the topic is ambiguous; for a clear question or subject, produce one primary interpretation plus any materially plausible alternative alternative, if one exists.
- Consider translations, transliterations, aliases, fictional and real-world meanings, and common usage.
- Do not promote a longer lexical lookalike merely because it contains the raw string.
- discovery_query must be an English web query that can independently test that candidate.
- candidate_id values must be C1, C2, ... and unique.
- Do not answer the topic and do not claim a winner without search evidence.`;
return [{json:{...j,raw_topic:topic,output_language_name:names[language],intent_prompt:prompt}}];

const candidateItems=$('Parse Semantic Intent').all().map(x=>x.json);const discoveryItems=$input.all().map(x=>x.json);if(!candidateItems.length||candidateItems.length!==discoveryItems.length)throw new Error('candidate discovery result count mismatch');const base=candidateItems[0];const candidates=base.semantic_candidates;const evidence=[];for(let i=0;i<candidateItems.length;i++){const cid=candidateItems[i].candidate_id;const rows=(Array.isArray(discoveryItems[i].results)?discoveryItems[i].results:[]).slice(0,6);for(let k=0;k<rows.length;k++){const x=rows[k];const title=String(x.title??'').replace(/\s+/gu,' ').trim(),snippet=String(x.content??x.description??'').replace(/\s+/gu,' ').trim(),url=String(x.url??'').trim();if(title&&snippet&&url)evidence.push({evidence_id:`D-${cid}-${k+1}`,candidate_id:cid,title,snippet,url});}}if(evidence.length<2)throw new Error('semantic discovery returned fewer than two usable results');const candidateText=candidates.map(c=>`${c.candidate_id} | ${c.canonical_name} | ${c.subject_type} | ${c.context}
Interpretation: ${c.interpretation}
Query: ${c.discovery_query}`).join('

');const evidenceText=evidence.map(x=>`${x.evidence_id} | candidate ${x.candidate_id} | ${x.title}
${x.snippet}
${x.url}`).join('

');const prompt=`You resolve the intended meaning of a raw user topic for an autonomous research pipeline. Compare all candidate interpretations against the raw wording, linguistic/common-usage plausibility, and supplied independent web-search evidence. Search rank alone and lexical substring similarity are not proof of intent.

