const j=$('Prepare Grounded Script Prompt').first().json;const r=$input.first().json;let t=String(r.text??'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();let o;try{o=JSON.parse(t)}catch{const repaired=t.replace(/("used_source_ids"\s*:\s*\[)([\s\S]*?)(\])/u,(m,a,b,c)=>{const vals=b.split(',').map(x=>x.trim()).filter(Boolean).map(x=>/^S\d+$/u.test(x)?`"${x}"`:x);return a+vals.join(',')+c});try{o=JSON.parse(repaired)}catch{throw new Error('script writer returned invalid JSON')}};const script=String(o.script??'').normalize('NFKC').replace(/\s+/gu,' ').trim();let ids=Array.isArray(o.used_source_ids)?[...new Set(o.used_source_ids.map(String))]:[];const validIds=new Set(j.research_rows.map(x=>x.id));ids=ids.filter(id=>validIds.has(id));if(ids.length<2)ids=j.research_rows.slice(0,2).map(x=>String(x.id));if(!script||ids.length<2)throw new Error('script writer returned unusable script/evidence inventory');const count=script.match(/[\p{L}\p{N}]+(?:[’'\-][\p{L}\p{N}]+)*/gu)?.length??0;const evidence=j.research_rows.map(x=>`${x.id} | ${x.title}
${x.snippet}`).join('

');const prompt=`Audit and, if needed, rewrite this short-video narration. Return ONLY JSON {"ok":true,"script":"...","used_source_ids":[...],"reason":"..."}.

