const j=$('Prepare Script Validation').first().json;const r=$input.first().json;let t=String(r.text??'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();let o;try{o=JSON.parse(t)}catch{const repaired=t.replace(/("used_source_ids"\s*:\s*\[)([\s\S]*?)(\])/u,(m,a,b,c)=>{const vals=b.split(',').map(x=>x.trim()).filter(Boolean).map(x=>/^S\d+$/u.test(x)?`\"${x}\"`:x);return a+vals.join(',')+c});try{o=JSON.parse(repaired)}catch{throw new Error('script validator returned invalid JSON')}};const script=String(o.script??'').normalize('NFKC').replace(/\s+/gu,' ').trim();const rowMap=new Map(j.research_rows.map(x=>[x.id,x]));let ids=Array.isArray(o.used_source_ids)?[...new Set(o.used_source_ids.map(String))]:[];let used=ids.filter(id=>rowMap.has(id));if(used.length<2){ids=[...new Set((j.draft_source_ids??[]).map(String))];used=ids.filter(id=>rowMap.has(id));}if(used.length<2){ids=j.research_rows.slice(0,2).map(x=>String(x.id));used=ids.filter(id=>rowMap.has(id));}if(!script||used.length<2)throw new Error('validated script or research evidence is incomplete');const wc=script.match(/[\p{L}\p{N}]+(?:[’'\-][\p{L}\p{N}]+)*/gu)?.length??0;if(wc<Math.max(18,j.target_word_min-15)||wc>j.target_word_max+20)throw new Error(`validated script length ${wc} is outside broad duration bounds`);
const selected_evidence=used.map((id,index)=>{const x=rowMap.get(id);return {evidence_id:id,source_id:id,source_language:'en',source_title:x.title,source_url:x.url,passage_id:'searx-snippet',section:null,evidence_text:x.snippet,selection_score:100-index,selection_rank:index+1}});
