const wps={en:2.55,pl:2.25,ru:2.45,uk:2.35}[j.language_code]??2.4;const predicted=wc/wps;return [{json:{job_id:j.job_id,topic:j.topic,language_code:j.language_code,target_duration_seconds:Number(j.target_duration_seconds),canonical_subject:j.canonical_subject,topic_resolution:j.topic_resolution,script_text:script,script_support,selected_evidence,duration_preflight:{version:'ai-word-budget-v1',language_code:j.language_code,target_duration_seconds:Number(j.target_duration_seconds),predicted_duration_seconds:Number(predicted.toFixed(3)),prediction_is_advisory:true,exact_tts_required:true},narration_engine:'grounded_ai_writer',narration_model:String(r.model??j.writer_model??'model-gateway'),narration_prompt_version:'grounded-writer-v1-topic-resolution-v1',script_fit_passes:0,fact_source_language:'en',fact_primary_title:j.canonical_subject,visual_search_queries_en:j.visual_search_queries_en}}];

const incoming=$input.first()?.json??{};
let jobId=String(incoming.job_id??incoming.requested_job_id??'').trim();
const recover=(name)=>{try{return String($(name).first().json?.job_id??$(name).first().json?.requested_job_id??'').trim()}catch{return ''}};
if(!jobId){for(const name of ['Build Final Grounded Script','Prepare Script Validation','Prepare Grounded Script Prompt','Parse Semantic Intent','Prepare Semantic Intent','Require Eligible Job','Load Eligible Job','Receive Job ID']){jobId=recover(name);if(jobId)break;}}
